INSERT INTO tb_produtos (nome_produto, preco_produto, descricao_produto, imagem_produto, id_categoria, descricao_detalhada)
VALUES ("Café Preto", 8.90, "Café puro e encorpado, feito com grãos selecionados e aroma marcante para o seu dia.", "../static/img/cafe-preto.jpg", 1, "Ingredientes: Água filtrada e café torrado e moído. Alérgicos: Não contém glúten. Não contém lactose."),
		("Café Descafeinado", 9.50, "Todo o sabor e aroma do café tradicional, em uma versão zero cafeína para qualquer hora do dia.", "../static/img/cafe-descafeinado.jpg", 1, "Ingredientes: Água filtrada e café torrado e moído descafeinado. Alérgicos: Não contém glúten. Não contém lactose."),
        ("Café com Leite", 11.00, "O clássico expresso com leite vaporizado, super cremoso e com uma espuma leve.", "../static/img/cafe-com-leite.jpg", 1, "Ingredientes: Café expresso e leite integral vaporizado. Alérgicos: Contém lactose e derivados de leite. Não contém glúten."),
        ("Café Gelado", 12.00, "O clássico café expresso refrescante, servido com gelo para renovar as suas energias.", "../static/img/cafe-gelado.jpg", 1, "Ingredientes: Café expresso selecionado, água filtrada e cubos de gelo. Alérgicos: Não contém glúten. Não contém lactose."),
        ("Café Gelado Caramelo", 16.50, "Uma combinação perfeita e gelada de café expresso, leite cremoso e uma calda doce de caramelo.", "../static/img/cafe-gelado-caramelo.jpg", 1, "Ingredientes: Café expresso, leite integral, calda de caramelo artesanal e cubos de gelo. Alérgicos: Contém lactose e derivados de leite. Não contém glúten."),
        ("Café Gelado Amargo", 14.00, "Para quem ama a intensidade do café puro, uma versão bem encorpada, gelada e sem açúcar.", "../static/img/cafe-gelado-amargo.jpg", 1, "Ingredientes: Café expresso duplo de torra escura, água filtrada e cubos de gelo. Alérgicos: Não contém glúten. Não contém lactose."),
        ("Milkshake Blueberry", 28.00, "Uma bebida super cremosa que une o sorvete premium com o toque cítrico e fresco do mirtilo.", "../static/img/milkshake-blueberry.jpg", 4, "Ingredientes: Uma base aveludada feita com sorvete premium de creme (rico em fava de baunilha), batido com leite integral gelado. O grande diferencial é a nossa calda artesanal de blueberries (mirtilos) frescos, cozida lentamente na própria casa para preservar os pedaços da fruta e garantir o equilíbrio perfeito entre a doçura e a acidez natural. Finalizado com uma generosa camada de chantilly levemente aerado. Alérgicos: Contém lactose e derivados de leite. Não contém glúten."),
        ("Milkshake Caramelo", 24.00, "O equilíbrio exato entre a cremosidade do sorvete e a intensidade do nosso caramelo tostado.", "../static/img/milkshake-caramelo.jpg", 4, "Ingredientes: Mistura clássica e encorpada de sorvete premium sabor creme com leite integral selecionado. O sabor marcante vem da nossa exclusiva calda de caramelo toffee artesanal, preparada na temperatura exata para atingir notas tostadas e profundas, sem ficar excessivamente doce. Servido com calda decorando o copo e topo de chantilly cremoso. Alérgicos: Contém lactose e derivados de leite. Não contém glúten."),
        ("Milkshake de Chocolate com Nozes", 28.00, "O sabor profundo do chocolate combinado com a crocância irresistível de nozes picadas.", "../static/img/milkshake-chocolateComNozes.jpg", 4, "Ingredientes: Batido com sorvete premium de chocolate nobre (com alto teor de cacau para garantir cor e sabor intensos) e leite integral. Adicionamos uma quantidade generosa de nozes chilenas selecionadas e levemente tostadas, picadas na medida certa para que apareçam a cada canudada trazendo crocância. Finalizado com calda de chocolate artesanal e chantilly. Alérgicos: Contém lactose e derivados de leite. Contém nozes. Pode conter traços de amendoim e castanhas. Não contém glúten."),
        ("Milkshake Meio Amargo", 26.00, "Uma sobremesa gelada e aveludada, feita sob medida para quem prefere o sabor robusto do cacau.", "../static/img/milkshake-meioAmargo.jpg", 4, "Ingredientes: Uma receita exclusiva para paladares maduros, que combina sorvete artesanal de chocolate meio amargo (50% cacau) e leite integral. O toque final fica por conta de uma redução de cacau puro em pó e chocolate derretido na consistência de ganache, criando texturas diferentes e um sabor profundo, robusto e perfeitamente equilibrado, longe de ser enjoativo. Alérgicos: Contém lactose e derivados de leite e soja. Não contém glúten."),
        ("Milkshake de Morango", 24.00, "Super refrescante e com gosto de infância, batido com uma calda artesanal de morangos frescos.", "../static/img/milkshake-morango.jpg", 4, "Ingredientes: Elaborado com sorvete premium de morango de verdade e leite integral bem gelado. O segredo do frescor está na nossa autêntica geleia rústica de morango, feita diariamente na nossa cozinha com frutas frescas e selecionadas, garantindo aquela cor vibrante e pequenas sementinhas da fruta que dão o toque natural à bebida. Finalizado com chantilly tradicional. Alérgicos: Contém lactose e derivados de leite. Não contém glúten."),
        ("Milkshake de Oreo", 26.00, "Muito cremoso e com pedacinhos crocantes do biscoito Oreo original do começo ao fim.", "../static/img/milkshake-oreo.jpg", 4, "Ingredientes: Base ultra cremosa de sorvete premium de baunilha batida com leite integral. Adicionamos biscoitos Oreo originais triturados de forma rústica: alguns pedaços viram um delicioso farelo que se mistura ao sorvete, enquanto pedaços maiores e crocantes ficam espalhados pela bebida para manter a textura do primeiro ao último gole. Coroado com chantilly e um biscoito inteiro no topo. Alérgicos: Contém lactose, glúten e derivados de leite, trigo e soja."),
		("Milkshake de Chocomenta", 26.00, "O frescor inconfundível da menta misturado com a riqueza de pedaços de chocolate nobre.", "../static/img/milkshake-chocomenta.jpg", 4, "Ingredientes: Uma combinação refrescante e sofisticada de sorvete premium sabor creme batido com leite integral e xarope natural concentrado de menta hortelã, que traz um frescor imediato. Para criar o contraste perfeito, misturamos delicadas raspas e gotas de chocolate nobre meio amargo, que derretem suavemente na boca a cada gole. Finalizado com chantilly. Alérgicos: Contém lactose e derivados de leite e soja. Não contém glúten."),
        ("Milkshake de Banana", 22.00, "Uma opção cremosa, leve e reconfortante feita com frutas frescas selecionadas e um toque de canela.", "../static/img/milkshake-banana.jpg", 4, "Ingredientes: Feito com bananas nanicas frescas e maduras, selecionadas no ponto ideal de doçura, batidas na hora junto com sorvete premium de creme e leite integral. A bebida ganha uma textura densa e naturalmente aveludada, finalizada com uma leve pitada de canela em pó polvilhada por cima do chantilly, criando um aroma e sabor acolhedores. Alérgicos: Contém lactose e derivados de leite. Não contém glúten."),
        ("Milkshake de Red Velvet", 29.00, "Toda a sofisticação do bolo Red Velvet em uma versão gelada com um toque leve de cream cheese.", "../static/img/milkshake-cookies.jpg", 4, "Ingredientes: Uma verdadeira sobremesa líquida que combina sorvete premium de baunilha, leite integral e pedaços generosos do nosso bolo Red Velvet artesanal (massa leve com toque sutil de cacau e cor vibrante). Para trazer a identidade do bolo original, adicionamos uma base cremosa de autêntico cream cheese e finalizamos com chantilly e farelos vermelhos do bolo para decorar. Alérgicos: Contém glúten, lactose, ovos e derivados de leite e trigo."),
        ("Brownie", 14.00, "O autêntico brownie americano: denso, super chocolatudo e com aquela casquinha craquelada irresistível.", "../static/img/brownie.jpg", 2, "Ingredientes: Preparado de forma artesanal com um blend exclusivo de chocolates nobres de alta qualidade e manteiga de verdade, o que garante a textura pesada, úmida e o sabor marcante. Não leva fermento, mantendo a tradição de uma massa rica e fudgy por dentro, finalizada com uma delicada e crocante casquinha brilhante por fora. Alérgicos: Contém glúten, lactose e ovos. Pode conter traços de nozes, amendoim e castanhas."),
        ("Cookies", 12.00, "Crocantes por fora, incrivelmente macios por dentro e carregados com gotas de chocolate puro.", "../static/img/cookies.jpg", 2, "Ingredientes: Feitos com uma receita tradicional americana que utiliza manteiga batida, açúcar mascavo (responsável pela umidade interna e toque caramelizado) e essência natural de baunilha. São assados no tempo e na temperatura exata para criar bordas douradas e um centro macio, recheado com fartas gotas de chocolate nobre que derretem na boca. Alérgicos: Contém glúten, lactose e ovos. Contém derivados de trigo, leite e soja. Pode conter traços de nozes e castanhas."),
        ("Torta de Morango", 22.00, "Uma sobremesa clássica, leve e refrescante que equilibra uma base amanteigada com o azedinho da fruta.", "../static/img/torta-morango.jpg", 2, "Ingredientes: Composta por uma base de massa brisée (massa podre) assada até ficar dourada e crocante na medida. O recheio leva um creme de confeiteiro artesanal suave, aromatizado com baunilha. A cobertura é feita com morangos frescos e selecionados, higienizados e cortados no dia, finalizados com uma leve geleia de brilho natural para proteger a fruta e dar o acabamento perfeito. Alérgicos: Contém glúten, lactose e ovos. Contém derivados de trigo e leite. Pode conter traços de oleaginosas."),
        ("Bomboms da casa", 26.00, "Uma seleção exclusiva de bombons finos feitos à mão, perfeitos para presentear ou adoçar o dia.", "../static/img/bomboms-da-casa.jpg", 2, "Ingredientes: Caixa composta por bombons moldados artesanalmente com chocolate nobre (ao leite e meio amargo), garantindo uma casca fina e crocante. Cada unidade é recheada com preparos cremosos da nossa confeitaria, variando entre brigadeiro gourmet, caramelo salgado texturizado, ganache de pistache e reduções de frutas. Alérgicos: Contém lactose, derivados de leite e soja. Pode conter glúten, ovos, amendoim, castanha-de-caju e nozes."),
        ("Biscoff", 26.00, "Uma sobremesa sofisticada que une a cremosidade única ao toque inconfundível de especiarias e caramelo.", "../static/img/biscoff.jpg", 2, "Ingredientes: Uma experiência premium estruturada com uma base crocante feita com os legítimos biscoitos belgas Lotus Biscoff triturados. O recheio ultra cremoso combina creme de leite fresco e o autêntico creme de cookie Biscoff, resultando em um sabor rico com notas marcantes de caramelo tostado, canela e especiarias europeias. Alérgicos: Contém glúten, derivados de trigo e soja, e lactose. Pode conter traços de ovos e oleaginosas."),
        ("Petit Gateau", 24.00, "O clássico bolinho de chocolate com o exterior assado e o recheio quentinho e cremoso.", "../static/img/petit-gateau.jpg", 2, "Ingredientes: Receita refinada feita com chocolate nobre de alta qualidade, manteiga fresca, ovos selecionados e uma quantidade mínima de farinha para dar estrutura. O segredo está no tempo preciso de forno, criando uma pequena camada firme por fora enquanto o centro permanece em estado líquido, transformando-se em uma calda quente e aveludada ao ser cortado. Alérgicos: Contém glúten, lactose e ovos. Contém derivados de trigo, leite e soja."),
        ("Banoffee", 21.00, "Camadas perfeitas de biscoito, doce de leite premium, bananas frescas e um chantilly super leve.", "../static/img/banofe.jpg", 2, "Ingredientes: Montada cuidadosamente em camadas começando por uma base crocante de biscoito de amido de milho com manteiga. Por cima, uma camada generosa de doce de leite cremoso e consistente, coberta por rodelas de bananas d'água frescas cortadas na hora. A finalização leva um chantilly artesanal fresco, super leve e aerado, polvilhado com cacau em pó puro para equilibrar a doçura. Alérgicos: Contém lactose, glúten e derivados de leite e trigo. Pode conter traços de ovos e oleaginosas."),
        ("Bolo Red Velvet", 23.00, "O icônico bolo de massa vermelha aveludada, com recheio cremoso e levemente cítrico de cream cheese.", "../static/img/red-velvet.jpg", 2, "Ingredientes: Fatias com massa de textura incrivelmente macia e úmida, preparada com um toque sutil de cacau em pó e buttermilk (leite fermentado), que dá a acidez correta à receita. O recheio e a cobertura são feitos com um autêntico e generoso frosting de cream cheese aerado com açúcar de confeiteiro e extrato natural de baunilha, criando um contraste impecável. Alérgicos: Contém glúten, lactose e ovos. Pode conter traços de oleaginosas."),
        ("Bolo de Chocolate", 19.00, "Bolo caseiro fofinho com sabor intenso de cacau e uma cobertura generosa de brigadeiro rústico.", "../static/img/bolo-chocolate.jpg", 2, "Ingredientes: Massa tradicional super fofinha e escura, feita com cacau em pó alcalino selecionado para garantir cor e sabor intensos, sem excesso de açúcar. O bolo é generosamente coberto e recheado com o nosso brigadeiro artesanal, cozido lentamente na panela com leite condensado, creme de leite fresco e chocolate, resultando em uma textura puxa-puxa brilhante. Alérgicos: Contém glúten, lactose e ovos. Pode conter traços de soja e oleaginosas."),
        ("Chá de Limão", 9.00, "Uma infusão quente, revigorante e perfeitamente cítrica, ideal para aquecer o corpo e a alma.", "../static/img/cha-limao.jpg", 3, "Ingredientes: Preparado através da infusão de folhas selecionadas de chá da Índia combinadas com raspas e fatias desidratadas de limão-taiti fresco. O processo extrai os óleos essenciais da casca da fruta, garantindo um aroma herbal marcante e uma acidez equilibrada que limpa o paladar. Alérgicos: Não contém glúten. Não contém lactose."),
        ("Chá de Hibisco", 9.50, "Uma infusão floral de cor rubi intensa, com sabor marcadamente aromático e levemente azedinho.", "../static/img/cha-hibisco.jpg", 3, "Ingredientes: Feito exclusivamente com os cálices desidratados da flor de Hibiscus sabdariffa de alta qualidade. A infusão resulta numa bebida de sabor robusto, notas frutadas que lembram o sabor do mirtilo e uma acidez natural super agradável, perfeita para ser consumida pura ou levemente adoçada. Alérgicos: Não contém glúten. Não contém lactose."),
        ("Chá Gelado de Limão", 11.50, "Ultra refrescante e gelado, combinando a energia do chá preto com o toque cítrico do limão.", "../static/img/cha-gelado.jpg", 3, "Ingredientes: Uma base concentrada de chá preto premium (extraído de folhas de Camellia sinensis), arrefecida rapidamente para preservar o sabor. É misturada com sumo fresco de limão espremido na hora, água filtrada e bastantes cubos de gelo, criando uma bebida leve, equilibrada e muito refrescante. Alérgicos: Não contém glúten. Não contém lactose."),
        ("Chá verde", 9.50, "Infusão clássica oriental, com sabor levemente vegetal e rica em propriedades antioxidantes.", "../static/img/cha-verde.jpg", 3, "Ingredientes: Preparado com folhas jovens de Camellia sinensis que passam por um processo de secagem a vapor logo após a colheita para evitar a oxidação. Isto garante a conservação da sua cor clara, aroma herbal característico e um sabor levemente adstringente e fresco. Alérgicos: Não contém glúten. Não contém lactose."),
        ("Chá Gelado de Pêssego", 13.00, "O sabor suave e aveludado do pêssego misturado com o frescor de um chá gelado perfeito.", "../static/img/cha-gelado-pessego.jpg", 3, "Ingredientes: Infusão gelada de chá preto selecionado combinado com um néctar artesanal de pêssegos maduros. A calda de fruta é incorporada delicadamente à bebida para trazer o dulçor natural e o aroma inconfundível do pêssego, servida com rodelas da fruta fresca e muito gelo. Alérgicos: Não contém glúten. Não contém lactose."),
        ("Chá de Camomila", 9.00, "A infusão calmante mais querida do mundo, ideal para relaxar e trazer uma sensação de paz.", "../static/img/cha-camomila.jpg", 3, "Ingredientes: Feito com as flores inteiras desidratadas de camomila (Matricaria chamomilla). A infusão destas flores liberta um aroma doce que lembra a maçã e um sabor extremamente suave, floral e reconfortante, perfeito para o final do dia ou momentos de pausa. Alérgicos: Não contém glúten. Não contém lactose."),
        ("Chá de Hortelã", 9.00, "Um clássico herbal intensamente aromático que traz um frescor imediato a cada gole.", "../static/img/cha-hortela.jpg", 3, "Ingredientes: Infusão preparada com folhas puras e selecionadas de hortelã-pimenta desidratada. A água quente liberta o mentol natural presente nas folhas, o que confere à bebida um sabor vivo, revigorante e uma sensação de frescor duradoura na boca, excelente para após as refeições.Alérgicos: Não contém glúten. Não contém lactose."),
        ("Chá Gelado de Frutas Vermelhas", 14.00, "Uma explosão gelada de sabores frutados, com uma cor vibrante e doçura na medida certa.", "../static/img/cha-gelado-fv.jpg", 3, "Ingredientes: Combinação refrescante obtida através do blend gelado de hibisco e chá preto, enriquecido com uma redução artesanal de morangos, amoras e framboesas frescas. A mistura é batida ligeiramente com cubos de gelo para apurar os sabores silvestres e a doçura natural das frutas. Alérgicos: Não contém glúten. Não contém lactose."),
        ("Chá Oolong", 13.00, "O sofisticado chá azul chinês, que equilibra perfeitamente o frescor do chá verde com o corpo do chá preto.", "../static/img/cha-oolong.jpg", 3, "Ingredientes: Infusão de folhas de Camellia sinensis que passam por um processo de oxidação parcial e artesanal. Esta técnica milenar confere ao Chá Oolong (também conhecido como Chá Azul) um perfil de sabor único, complexo e elegante, com notas florais suaves, um toque amendoado e um final de boca prolongado. Alérgicos: Não contém glúten. Não contém lactose.");
        
        
